from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

# Error messages produced for malformed input. Preserved as public contract.
_ERR_MALFORMED = "malformed input"
_ERR_MISSING = "missing field"
_ERR_BAD_GRID = "bad grid"
_ERR_BAD_WIDTH = "bad width"
_ERR_BAD_HEIGHT = "bad height"
_ERR_BAD_CELL = "bad cell size"
_ERR_BAD_FILL = "bad fill value"
_ERR_BAD_OBSERVATIONS = "bad observations"
_ERR_BAD_OBSERVATION = "bad observation"

# Fields required on each structured input level.
_REQUIRED_RAW_FIELDS = ("grid", "observations", "fill_value")
_REQUIRED_GRID_FIELDS = ("width", "height", "cell_size")
_REQUIRED_OBS_FIELDS = ("x", "y", "value", "quality")


def accumulate_grid(raw: object) -> dict:
    """Aggregate observations into a grid of average values.

    Returns a dict with the averaged ``cells``, per-cell ``flags`` and summary
    counters, or an ``{"ok": False, "error": ...}`` dict for malformed input.
    """
    if not isinstance(raw, dict):
        return _failure(_ERR_MALFORMED)
    if not all(f in raw for f in _REQUIRED_RAW_FIELDS):
        return _failure(_ERR_MISSING)

    grid = raw["grid"]
    if not isinstance(grid, dict):
        return _failure(_ERR_BAD_GRID)
    if not all(f in grid for f in _REQUIRED_GRID_FIELDS):
        return _failure(_ERR_BAD_GRID)

    width = grid["width"]
    height = grid["height"]
    cell_size = grid["cell_size"]
    if not isinstance(width, int) or not 1 <= width <= MAX_DIM:
        return _failure(_ERR_BAD_WIDTH)
    if not isinstance(height, int) or not 1 <= height <= MAX_DIM:
        return _failure(_ERR_BAD_HEIGHT)
    if not isinstance(cell_size, int) or cell_size < 1:
        return _failure(_ERR_BAD_CELL)

    fill_value = raw["fill_value"]
    if not isinstance(fill_value, int):
        return _failure(_ERR_BAD_FILL)

    observations = raw["observations"]
    if not isinstance(observations, list):
        return _failure(_ERR_BAD_OBSERVATIONS)

    sums: dict = {}
    counts: dict = {}
    degraded: dict = {}
    dropped = rejected = saturated = 0
    tolerance = cell_size // 2

    for obs in observations:
        if not _valid_observation(obs):
            return _failure(_ERR_BAD_OBSERVATION)

        if obs["quality"] < MIN_QUALITY:
            rejected += 1
            continue

        row, dropped_in_row = _project(obs["y"], cell_size, height)
        if dropped_in_row:
            dropped += 1
            continue
        col, dropped_in_col = _project(obs["x"], cell_size, width)
        if dropped_in_col:
            dropped += 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    total_cells = width * height
    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = _coverage(counts, total_cells)
    line = _summary_line(total_cells, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _failure(error: str) -> dict:
    return {"ok": False, "error": error}


def _valid_observation(obs: object) -> bool:
    """Validate an observation record, or return False.

    Pop: also rejects quality values outside the documented [0, 100] range.
    """
    if not isinstance(obs, dict):
        return False
    if not all(f in obs for f in _REQUIRED_OBS_FIELDS):
        return False
    if not all(isinstance(obs[f], int) for f in _REQUIRED_OBS_FIELDS):
        return False
    return 0 <= obs["quality"] <= 100


def _project(coord: int, cell_size: int, limit: int) -> tuple:
    """Map a coordinate onto a grid index.

    Returns ``(index, False)`` for a coordinate that belongs to a column/row
    (with a small tolerance for coordinates just past the last index), or
    ``(None, True)`` when the coordinate falls out of range and must be dropped.
    """
    if coord < 0:
        return None, True
    index = coord // cell_size
    if index >= limit:
        if coord - limit * cell_size < cell_size // 2:
            return limit - 1, False
        return None, True
    return index, False


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    """Build the grid of averaged values, filling empty cells with fill_value."""
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    """Classify every cell as empty, good or degraded."""
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _coverage(counts: dict, total_cells: int) -> int:
    return len(counts) * 100 // total_cells


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

